<form method="post" enctype="multipart/form-data"><?= csrf() ?><input type="hidden" name="action" value="upload">
<label class="upload-zone"><span class="upload-zone-title"><?= ui_icon('upload', 22) ?>Selecciona los PDF de esta atención</span><input name="pdfs[]" type="file" accept="application/pdf,.pdf" multiple required><small>Selecciona el paquete completo de una sola atención. Máximo 15 PDF. Hasta <?= h(round($uploadLimits['file_bytes']/1024**2,1)) ?> MB por archivo.</small></label>
