<label class="check"><input type="checkbox" name="complete" value="1" required><span>Estos archivos componen la historia completa de una misma atención.</span></label><div class="sheet-foot"><a class="button secondary" href="#" data-close>Cancelar</a><button class="button primary"><?= ui_icon('file', 18) ?>Leer y guardar historia</button></div></form>
